import{_ as s,o as a,c as n}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"Page 4 - web | Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"web/page/4","tag":"web","title":"Page 4 - web | Tag","prev":"/tags/web/page/3/","next":"/tags/web/page/5/","posts":[{"title":"vue实现datepicker组件","url":"/posts/2020-11-30-vue-datepicker/","date":"2020-11-30 14:07","tags":["web","vue"],"html":"<p>前端组件化的今天，选择日期组件算是最复杂的一个了吧。我们需要考虑日期显示的多语言，弹框的显示位置，以及日期月份的计算。</p>\\n<h2 id=\\"日期相关计算\\" tabindex=\\"-1\\">日期相关计算 <a class=\\"header-anchor\\" href=\\"#日期相关计算\\" aria-label=\\"Permalink to &quot;日期相关计算&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>计算每个月的天数，这个是不变的。一三五七八十腊，三十一天永不差；四六九冬三十整，惟有二月二十八，闰年还要把一日加。</p>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> getDayCountOfMonth</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">year</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">month</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (month </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#005CC5\\"> 3</span><span style=\\"color:#D73A49\\"> ||</span><span style=\\"color:#24292E\\"> month </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#005CC5\\"> 5</span><span style=\\"color:#D73A49\\"> ||</span><span style=\\"color:#24292E\\"> month </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#005CC5\\"> 8</span><span style=\\"color:#D73A49\\"> ||</span><span style=\\"color:#24292E\\"> month </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#005CC5\\"> 10</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#005CC5\\"> 30</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (month </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#005CC5\\"> 1</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    if</span><span style=\\"color:#24292E\\"> ((year </span><span style=\\"color:#D73A49\\">%</span><span style=\\"color:#005CC5\\"> 4</span><span style=\\"color:#D73A49\\"> ===</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#D73A49\\"> &#x26;&#x26;</span><span style=\\"color:#24292E\\"> year </span><span style=\\"color:#D73A49\\">%</span><span style=\\"color:#005CC5\\"> 100</span><span style=\\"color:#D73A49\\"> !==</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">||</span><span style=\\"color:#24292E\\"> year </span><span style=\\"color:#D73A49\\">%</span><span style=\\"color:#005CC5\\"> 400</span><span style=\\"color:#D73A49\\"> ===</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      return</span><span style=\\"color:#005CC5\\"> 29</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    } </span><span style=\\"color:#D73A49\\">else</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      return</span><span style=\\"color:#005CC5\\"> 28</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#005CC5\\"> 31</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br></div></div><p>计算每个月的 1 号是周几：</p>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> getFirstDayOfMonth</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">date</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Date</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> temp</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> Date</span><span style=\\"color:#24292E\\">(date.</span><span style=\\"color:#6F42C1\\">getTime</span><span style=\\"color:#24292E\\">());</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  temp.</span><span style=\\"color:#6F42C1\\">setDate</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> temp.</span><span style=\\"color:#6F42C1\\">getDay</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><p>其他计算函数可以去看完整代码<a href=\\"https://github.com/acgotaku/vue-datepicker/blob/master/src/utils/date.ts\\" target=\\"_blank\\" rel=\\"noreferrer\\">date.ts</a></p>\\n<h2 id=\\"弹窗定位相关\\" tabindex=\\"-1\\">弹窗定位相关 <a class=\\"header-anchor\\" href=\\"#弹窗定位相关\\" aria-label=\\"Permalink to &quot;弹窗定位相关&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>点击日期输入框，需要弹出下拉菜单，下拉菜单位置的计算并不简单，需要考虑到浏览器的窗口，如果输入框在下方，需要在上方弹出，如果输入框在上方，需要在下方弹出。\\n并且用户滑动到可视范围以外的话，还要可以隐藏。所以我们这里引用了一个比较成熟的第三方库来解决这个问题。\\n<a href=\\"https://github.com/popperjs/popper-core\\" target=\\"_blank\\" rel=\\"noreferrer\\">popperjs</a>\\n这个库可以帮我们解决上面的问题，节约开发的成本。</p>\\n<h2 id=\\"多语言支持\\" tabindex=\\"-1\\">多语言支持 <a class=\\"header-anchor\\" href=\\"#多语言支持\\" aria-label=\\"Permalink to &quot;多语言支持&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>日期选择组件，是为数不多需要做多语言支持的组件。因为我们要显示月份和每周的名字。就不得不做多语言处理了。目前我做的 demo 里面包含了三种语言的支持。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>日期选择组件，常见的需求有单日期选择和日期范围选择。优秀的组件需要同时满足这两个需求。并且尽量保证代码的简洁性。为此，我在 Github 写了一个 demo 库，希望可以给大家参考。</p>\\n<p><a href=\\"https://github.com/acgotaku/vue-datepicker\\" target=\\"_blank\\" rel=\\"noreferrer\\">vue-datepicker</a></p>\\n"},{"title":"前端中debounce和throttle函数说明","url":"/posts/2020-10-17-debounce-and-throttle/","date":"2020-10-17 20:52","tags":["web"],"html":"<p>前端开发中，debounce 和 throttle 函数经常会被使用，但是很多人分不清两者的区别，今天就来说明一下。</p>\\n<h2 id=\\"debounce\\" tabindex=\\"-1\\">debounce <a class=\\"header-anchor\\" href=\\"#debounce\\" aria-label=\\"Permalink to &quot;debounce&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们首先来看 debounce (防抖动)的代码实现：</p>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> debounce</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#6F42C1\\">fn</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Function</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">time</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Function</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  let</span><span style=\\"color:#24292E\\"> timeout </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">...</span><span style=\\"color:#E36209\\">args</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> any</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    window.</span><span style=\\"color:#6F42C1\\">clearTimeout</span><span style=\\"color:#24292E\\">(timeout);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    timeout </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> window.</span><span style=\\"color:#6F42C1\\">setTimeout</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">      fn</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#D73A49\\">...</span><span style=\\"color:#24292E\\">args);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }, time);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br></div></div><p>从代码中可以看出，该函数在执行的时候会清除上次的定时器，然后设置一个新的定时器，等待一定时间之后执行。所以在短时间内调用多次的话，只会执行最后一次。</p>\\n<h2 id=\\"throttle\\" tabindex=\\"-1\\">throttle <a class=\\"header-anchor\\" href=\\"#throttle\\" aria-label=\\"Permalink to &quot;throttle&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>throttle (节流)函数的代码实现：</p>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> throttle</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#6F42C1\\">fn</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Function</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">time</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Function</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  let</span><span style=\\"color:#24292E\\"> inThrottle</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> boolean</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">...</span><span style=\\"color:#E36209\\">args</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> any</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">!</span><span style=\\"color:#24292E\\">inThrottle) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      inThrottle </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">      fn</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#D73A49\\">...</span><span style=\\"color:#24292E\\">args);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">      setTimeout</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> (inThrottle </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">), time);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br></div></div><p>从代码中可以看出，函数在设置的阈值时间之内只会执行一次。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>debounce: 将频繁触发的事件合并为一次执行，适用场景例如输入名称进行搜索，使用 debounce 可以减少对服务器的请求，在用户输入完毕之后再进行请求。</p>\\n<p>throttle： 设置一个阈值，在阈值内函数只会执行一次，例如 resize 事件或者 scoll 事件，防止浏览器频繁执行，降低网页响应速度。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://css-tricks.com/the-difference-between-throttling-and-debouncing/\\" target=\\"_blank\\" rel=\\"noreferrer\\">The Difference Between Throttling and Debouncing</a></p>\\n"},{"title":"Web离线的解决方案","url":"/posts/2018-07-06-offline-web/","date":"2018-07-06 23:25","tags":["web","offline"],"html":"<p>最近的工作是做嵌入在 iOS 程序内部的页面，其中有一个需求就是需要满足在离线的情况下显示页面。当然，现在主流的离线方式是使用 Service Worker 来完成离线需求。\\n但是 iOS 内置的 WKWebView 并不支持最新的 Service Worker（取决于 iOS 版本）最新版本已经支持，所以不得不想办法来解决。</p>\\n<h2 id=\\"application-cache\\" tabindex=\\"-1\\">Application Cache <a class=\\"header-anchor\\" href=\\"#application-cache\\" aria-label=\\"Permalink to &quot;Application Cache&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>AppCache 是一个过时的技术，但是在 iOS 下勉强还能用。不过 Chrome 对这种过时的技术支持不是很好，单个缓存文件最大只支持 5MB。而且还有请求的 BUG:<a href=\\"https://bugs.chromium.org/p/chromium/issues/detail?id=140445\\" target=\\"_blank\\" rel=\\"noreferrer\\">Accept header on GET request for appcache manifest</a>。触发 AppCache 是在 html 标签中添加 manifest 属性。</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">html</span><span style=\\"color:#6F42C1\\"> manifest</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"manifest.appcache\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  ...</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#22863A\\">html</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>通过<code>manifest.appcache</code>文件来定义需要缓存的文件，不过载入<code>manifest.appcache</code>的页面会被作为<code>Master entries</code>缓存起来。因为 AppCache 出现的时候还是以静态网站为主，所以并不能缓存请求的 Ajax 数据。我们需要自己再手动实现缓存所有请求在<code>localStorage</code>，但是<code>localStorage</code>同样也有最大 5MB 的限制。所以也需要考虑相应的解决方案。不过，我最终采取的方式是通过嵌入<code>iframe</code>来实现触发 AppCache，这样做的好处是因为 SPA 应用是自己来控制路由的，所以导致每个路径都会保存一份<code>Master entries</code>。但是通过 iframe 的话，我们的<code>Master entries</code>永远只有一份。并且当前页面的所有资源也被顺利缓存，因为 SPA 无论访问哪个路径返回的都是相同的<code>index.html</code>。由 JS 来控制路由并加载相应的组件。</p>\\n<p>这里要补充的一点是，针对 https 的 Application Cache 是无法完成跨域请求的，所以请慎重。</p>\\n<h2 id=\\"workbox\\" tabindex=\\"-1\\">WorkBox <a class=\\"header-anchor\\" href=\\"#workbox\\" aria-label=\\"Permalink to &quot;WorkBox&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Service Worker 是现在主流的缓存技术，会帮你缓存所有的静态文件和数据请求。但是对于 SPA 项目，我们不可能自己手动书写缓存清单。所以还是借助现有的开源解决方案，这里最出名的解决方案是谷歌的 Workbox。通过使用 Webpack 插件和简单的配置，我们便可以做到缓存所有的静态资源和数据。Service Worker 有很多种缓存策略可以选择，例如 Cache First 和 NetWork First。但是 AppCache 每次都会优先使用缓存，然后再去更新最新的文件。所以我们不得不在发生更新的时候去重新加载页面。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>最终的解决方案是优先使用 Service Worker，当不支持 Service Worker 的时候再回退到 AppCache。但是想要从 AppCache 升级到 Service Worker 的时候，必须清除所有 AppCache 的所有数据。浏览器并没有提供相应的接口，我们目前采用的方式是手动删除 AppCache 储存的数据库来完成这一需求。</p>\\n<p>参考：</p>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTML/Using_the_application_cache\\" target=\\"_blank\\" rel=\\"noreferrer\\">Using the application cache</a></p>\\n<p><a href=\\"https://developer.apple.com/library/archive/documentation/iPhone/Conceptual/SafariJSDatabaseGuide/OfflineApplicationCache/OfflineApplicationCache.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">HTML5 Offline Application Cache</a></p>\\n<p><a href=\\"https://github.com/lettertwo/appcache-webpack-plugin\\" target=\\"_blank\\" rel=\\"noreferrer\\">Application Cache plugin for Webpack</a></p>\\n<p><a href=\\"https://developers.google.com/web/tools/workbox/modules/workbox-webpack-plugin\\" target=\\"_blank\\" rel=\\"noreferrer\\">Workbox webpack Plugins</a></p>\\n<p><a href=\\"https://appcachefacts.info/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Appcache Facts</a></p>\\n"}]},"relativePath":"tags/web/page/4/index.md","filePath":"tags/[slug].md"}'),e={name:"tags/web/page/4/index.md"};function p(l,o,r,t,c,i){return a(),n("div")}const h=s(e,[["render",p]]);export{b as __pageData,h as default};
